import{z as i,x as s,o as B,c as n,q as l,j as e,D as a,d as t,s as o,S as r}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"KV 管理收束","description":"","frontmatter":{"title":"KV 管理收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/kv-map.md","filePath":"llm/kv-map.md","lastUpdated":1791063341000}'),p={name:"llm/kv-map.md"};function d(D,E,m,C,f,_){const A=s("Mermaid");return B(),n("div",null,[E[2]||(E[2]=l('<h1 id="kv-管理收束" tabindex="-1">KV 管理收束 <a class="header-anchor" href="#kv-管理收束" aria-label="Permalink to &quot;KV 管理收束&quot;">​</a></h1><div class="epigraph"><p>收束不是把十三课再讲一遍，而是把它们压成一张能贴在工位上的决策单：先做什么、后做什么、什么永远不碰。</p><footer>—— 据 Kwon et al., SOSP 2023 与 Pope et al., 2022 的系统口径，按本课程整理</footer></div><p><a href="/llm/kv-cost-model">上一课</a>把字节换成了钱：四笔账摆上桌，「值不值」有了统一的算法。至此这门课的零件齐了——所有权、分页、共享、量化、敏感度、驱逐、合并、预算、投机、分布式、测量、成本——本课收束：把它们装配成一张地图和一张决策单。上游是<a href="/llm/ak-map">注意力内核工程</a>回答的「核怎么读缓存」，下游是调度回答「谁先用池子」，本课程回答中间这一层：缓存本身怎么管。<strong>本课程到此收束。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>十三个决策点分布在系统各层，各自局部最优会互相拆台：量化改<a href="/llm/kv-prefix-cache">指纹</a>使共享失效，驱逐改变<a href="/llm/kv-longcontext-budget">长度分布</a>使预算失真，迁移挤占 decode 的网，压缩收益被<a href="/llm/kv-measurement-pitfalls">错误的口径</a>掩埋。没有全局顺序，团队会在错误的位置先动刀——最常见的两条弯路是：跳过分页直接上 2-bit 量化（先做有损的，后做无损的），以及不上前缀共享先调参数（把可买断的重算当成性能问题调）。收束要给的就是这张先后表。</p><p><span class="marginnote">直觉类比：十三个决策点像一桌各做各菜的大厨——量化改了指纹，共享那桌备好的菜就作废了；驱逐改了长度分布，预算那桌的账全错。收束单就是上菜顺序表：谁先出锅、谁用谁剩下的料，避免互相拆台。</span></p>',6)),(B(),e(r,null,{default:a(()=>[o(A,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%8B%BF%E5%88%B0%E4%B8%80%E6%B2%93%20KV%20%E4%BC%98%E5%8C%96%E9%9C%80%E6%B1%82%22%5D%20--%3E%20W1%5B%22%E5%BC%AF%E8%B7%AF%E4%B8%80%3A%20%E8%B7%B3%E8%BF%87%E5%88%86%E9%A1%B5%E7%9B%B4%E6%8E%A5%E4%B8%8A%202-bit%20%E9%87%8F%E5%8C%96%22%5D%0A%20%20W1%20--%3E%20W1b%5B%22%E5%85%88%E5%81%9A%E6%9C%89%E6%8D%9F%E7%9A%84%2C%20%E5%90%8E%E5%81%9A%E6%97%A0%E6%8D%9F%E7%9A%84%3A%20%E8%B4%A8%E9%87%8F%E5%85%88%E6%8E%89%2C%20%E5%AE%B9%E9%87%8F%E5%90%8E%E7%9C%81%22%5D%0A%20%20S%20--%3E%20W2%5B%22%E5%BC%AF%E8%B7%AF%E4%BA%8C%3A%20%E4%B8%8D%E4%B8%8A%E5%89%8D%E7%BC%80%E5%85%B1%E4%BA%AB%E5%85%88%E8%B0%83%E5%8F%82%E6%95%B0%22%5D%0A%20%20W2%20--%3E%20W2b%5B%22%E6%8A%8A%E5%8F%AF%E4%BB%A5%E4%B9%B0%E6%96%AD%E7%9A%84%E9%87%8D%E7%AE%97%E5%BD%93%E6%88%90%E6%80%A7%E8%83%BD%E9%97%AE%E9%A2%98%E5%8E%BB%E8%B0%83%22%5D%0A%20%20S%20--%3E%20R%5B%22%E6%AD%A3%E7%A1%AE%E6%8E%92%E5%BA%8F%E5%8E%9F%E5%88%99%3A%20%E6%97%A0%E6%8D%9F%E5%85%88%E4%BA%8E%E6%9C%89%E6%8D%9F%22%5D%0A%20%20R%20--%3E%20R1%5B%22%E5%88%86%E9%A1%B5%20%E2%86%92%20%E5%85%B1%E4%BA%AB%20%E2%86%92%208-bit%20%E2%86%92%20%E5%86%8D%E8%B0%88%E6%9B%B4%E7%8B%A0%E7%9A%84%E5%88%80%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[t(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=l('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>决策单</strong>，按「误差性质递增、边际成本递增」排序：</p><ol><li><strong>分页与水位</strong>：无损，拿回预留与碎片的容量，是一切的前提。</li><li><strong>前缀共享与缓存感知路由</strong>：无损，省重算与容量期望；命中靠放置，不靠运气。</li><li><strong>KV 8-bit</strong>：近似但稳，容量与带宽的系数同时砍半；核兑现事务宽度。</li><li><strong>逐层逐头差异化</strong>：把 3 的残余误差按<a href="/llm/kv-layerwise-sensitivity">敏感度表</a>重排，平均比特不变。</li><li><strong>驱逐</strong>：可见集换预算，误杀不可逆；滑窗+sink 是保底，分数法看负载。</li><li><strong>合并与蒸馏</strong>：高冗余处优于驱逐；可训练则走向 MLA/Beacon 一类架构化压缩。</li><li><strong>offload 与分层</strong>：把容量账换成介质账，按 \\(T^*\\) 定冷热。</li><li><strong>分布式与迁移</strong>：单机拿不出来才上集群；先路由后搬运，重算兜底定价。</li></ol><p>每一步都拿上一步吐不出的余量；任何一步的收益要在<a href="/llm/kv-measurement-pitfalls">测量</a>与<a href="/llm/kv-cost-model">成本</a>口径下联评后才算数。永不碰的三件事：共享页就地写（所有权）、跨口径比较利用率（测量）、只报吞吐不报任务质量（验收）。</p>',4)),(B(),e(r,null,{default:a(()=>[o(A,{id:"mermaid-68",class:"mermaid",graph:"flowchart%20TD%0A%20%20OWN%5B%22%E6%89%80%E6%9C%89%E6%9D%83%E4%B8%8E%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%20--%3E%20PAGE%5B%22%E5%88%86%E9%A1%B5%E4%B8%8E%E6%B0%B4%E4%BD%8D%22%5D%0A%20%20PAGE%20--%3E%20SHARE%5B%22%E5%89%8D%E7%BC%80%E5%85%B1%E4%BA%AB%20%2B%20%E8%B7%AF%E7%94%B1%22%5D%0A%20%20SHARE%20--%3E%20Q8%5B%22KV%208-bit%22%5D%0A%20%20Q8%20--%3E%20SENS%5B%22%E9%80%90%E5%B1%82%E9%80%90%E5%A4%B4%E5%B7%AE%E5%BC%82%E5%8C%96%22%5D%0A%20%20SENS%20--%3E%20EVICT%5B%22%E9%A9%B1%E9%80%90%22%5D%0A%20%20EVICT%20--%3E%20MERGE%5B%22%E5%90%88%E5%B9%B6%E4%B8%8E%E8%92%B8%E9%A6%8F%22%5D%0A%20%20MERGE%20--%3E%20OFF%5B%22offload%20%2F%20%E5%88%86%E5%B1%82%22%5D%0A%20%20OFF%20--%3E%20DIST%5B%22%E5%88%86%E5%B8%83%E5%BC%8F%E4%B8%8E%E8%BF%81%E7%A7%BB%22%5D%0A%20%20PAGE%20--%3E%20BUD%5B%22%E9%A2%84%E7%AE%97%EF%BC%9A%E5%AE%B9%E9%87%8F%E4%B8%8E%E5%B8%A6%E5%AE%BD%E4%B8%A4%E8%A1%A8%22%5D%0A%20%20SHARE%20--%3E%20BUD%0A%20%20Q8%20--%3E%20BUD%0A%20%20BUD%20--%3E%20SPEC%5B%22%E6%8A%95%E6%9C%BA%EF%BC%9A%E5%B3%B0%E5%80%BC%E4%B8%8E%E5%9B%9E%E6%BB%9A%22%5D%0A%20%20BUD%20--%3E%20DIST%0A%20%20SPEC%20--%3E%20MEAS%5B%22%E6%B5%8B%E9%87%8F%EF%BC%9A%E5%8F%8C%E5%8F%A3%E5%BE%84%20%2B%20%E5%AF%B9%E7%85%A7%22%5D%0A%20%20DIST%20--%3E%20MEAS%0A%20%20MEAS%20--%3E%20COST%5B%22%E6%88%90%E6%9C%AC%EF%BC%9A%E5%9B%9B%E7%AC%94%E8%B4%A6%E4%B8%8E%20T*%22%5D%0A%20%20COST%20--%3E%20DONE%5B%22%E6%94%B6%E6%9D%9F%EF%BC%9A%E5%86%B3%E7%AD%96%E5%8D%95%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[t(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>顺序背后的机制是不变式与参数的分层：所有权与口径是不变式，破了它们，任何参数调优都在错误的账本上计算；分页到迁移是参数，按误差性质排序——无损操作永远先于有损操作，因为后者的收益评估依赖前者的账已经干净。另一个机制是<strong>互补而非替代</strong>：MLA、GQA 把压缩买进权重，是训练期的另一条路线，与本课程的推理期管理不冲突——架构给的每一档压缩，推理期的刀照样在余量上继续生效，只是基数变了。</p><p><span class="marginnote">术语翻译：不变式就是「无论怎么调参数都不许违反的规则」——例如共享页绝不就地写、利用率必须同口径比较；参数才是可以拧的旋钮，例如用几 bit、留多少页。先守住不变式再拧旋钮，否则拧得越勤，账错得越快。</span></p><p><span class="marginnote">一张自检表：如果只能做三件事——先开分页与水位，再配前缀共享加缓存感知路由，然后把 KV 打到 8-bit 并核对 profiler 的事务宽度。多数服务在第三步之前就已拿到大半收益，后面的每一刀都要求先证明前面拿不出来了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这张地图有时效。架构侧：潜变量注意力一类设计把压缩买进权重，推理期管理的基数变小，但四刀的相对顺序不变。硬件侧：HBM 容量与单价的代际变化会移动 \\(T^*\\) 与预算表的每一个常数。负载侧：长文档、多轮 agent、MoE 专家缓存各有自己的瓶颈位，决策单的顺序要在真实负载上重验。收束也不是终点：缓存管好之后，瓶颈移向调度与多租户，移向长上下文系统工程的另一头——本课程交付的是中间这一层的地图，地图之外的路，由相邻课程接棒。</p><p><span class="marginnote">常见误区：把这张决策单当成一次性项目——做到第八步就归档。它实际是随模型升级、硬件换代、负载漂移要重跑的体检表；每换一版基座就从第一步重新过一遍，前几步通常又有新余量可拿。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>决策单按误差性质排序：分页 → 共享 → 8-bit → 逐层差异化 → 驱逐 → 合并 → offload → 分布式。</li><li>所有权与测量口径是不变式，破了它们一切调优都算错账。</li><li>每一步拿上一步吐不出的余量；收益在测量与成本口径下联评。</li><li>训练期压缩（GQA/MLA）与推理期管理互补：基数变了，刀的顺序不变。</li><li>三件永不碰：共享页就地写、跨口径比利用率、只报吞吐不报质量。</li><li>出处：本课程十三课的综合口径；底层文献锚点为 Kwon et al., SOSP 2023 与 Pope et al., 2022。</li></ul>',9))])}const S=i(p,[["render",d]]);export{F as __pageData,S as default};
